import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.tVbs9ddD.js";const m=JSON.parse('{"title":"How-to: summarizers","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/llm-summarizer.md","filePath":"how-to/llm-summarizer.md"}'),o={name:"how-to/llm-summarizer.md"};function n(r,e,l,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="how-to-summarizers" tabindex="-1">How-to: summarizers <a class="header-anchor" href="#how-to-summarizers" aria-label="Permalink to &quot;How-to: summarizers&quot;">​</a></h1><p><code>kuda-cards</code> turns extractions into the committed YAML artifacts. The <code>summarize</code> port has one shipping adapter — <code>template</code> — and one planned — <code>llm</code>.</p><h2 id="template-default-shipping" tabindex="-1"><code>template</code> (default, shipping) <a class="header-anchor" href="#template-default-shipping" aria-label="Permalink to &quot;`template` (default, shipping)&quot;">​</a></h2><p>Deterministic, zero-model. Each module card&#39;s <code>purpose</code> comes from the manifest <code>description</code> field (Cargo.toml <code>[package].description</code>, package.json <code>description</code>); <code>api</code> lists the extracted public symbols; <code>deps</code> lists the module&#39;s edges; <code>verify:</code> lists the files the card was built from.</p><p>Because it is mechanical, <code>template</code> output is stable — the same inputs always produce the same card, so diffs mean real change. That is the property you want in committed, reviewed artifacts.</p><h2 id="llm-planned-adapter" tabindex="-1"><code>llm</code> (planned adapter) <a class="header-anchor" href="#llm-planned-adapter" aria-label="Permalink to &quot;`llm` (planned adapter)&quot;">​</a></h2><p>Adds prose the manifest cannot carry: purpose narrative, invariants, &quot;who calls me and why&quot;. Design constraints for when it lands:</p><ul><li><strong>Grounded or silent</strong> — every generated claim cites the files it came from; uncited prose is not emitted.</li><li><strong>Never replaces <code>verify:</code></strong> — the file list stays mechanical.</li><li><strong>Human regions preserved</strong> — <code>notes:</code> in cards is human-owned; regeneration merges, never clobbers.</li><li><strong>Key resolution</strong> — <code>provider</code>/<code>model</code> in <code>kuda.toml</code>, the key itself via <code>KUDA_LLM_KEY</code> env → OS keyring → <code>~/.config/kuda/env</code>. Never in the file.</li></ul><h2 id="choosing" tabindex="-1">Choosing <a class="header-anchor" href="#choosing" aria-label="Permalink to &quot;Choosing&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">summarize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;template&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # deterministic (default)</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># kind = &quot;llm&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># provider = &quot;anthropic&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># model = &quot;...&quot;</span></span></code></pre></div><p>Until <code>llm</code> ships, the meaningful <code>purpose:</code> source is the manifest <code>description</code> — worth writing well, since it becomes part of the agent-facing map.</p>',11)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
